export interface Division {
  id: string;
  nameEn: string;
  nameBn: string;
}

export interface DistrictGeo {
  id: string;
  nameEn: string;
  nameBn: string;
  divisionId: string;
  cx: number; // Exact geographic centroid X on 825x1075 coordinate system
  cy: number; // Exact geographic centroid Y on 825x1075 coordinate system
  svgPath: string; // High-precision SVG boundary path on 825x1075 viewBox
}

export interface DistrictMapCoordinate {
  x: number;
  y: number;
  labelPos?: 'top' | 'right' | 'bottom' | 'left';
  labelOffsetX?: number;
  labelOffsetY?: number;
  isKeyVisual?: boolean;
}

